changeSet.sql:
ALTER TABLE gofp_relay_points ADD COLUMN IF NOT EXISTS parcel_capacity INTEGER;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_gofp_relay_points_parcel_capacity') THEN
        ALTER TABLE gofp_relay_points ADD CONSTRAINT ck_gofp_relay_points_parcel_capacity
            CHECK (parcel_capacity IS NULL OR parcel_capacity > 0);
    END IF;
END $$;
